// Convert ZB XML string to binary file for Google Drive upload
const data = $input.item.json;
const xmlContent = data.zbXML;
const fileName = data.xmlFileName || `ZB_${Date.now()}.xml`;
const base64 = Buffer.from(xmlContent, 'utf8').toString('base64');

return {
  json: data,
  binary: {
    data: {
      data: base64,
      mimeType: 'application/xml',
      fileName: fileName,
      fileExtension: 'xml'
    }
  }
};

const fileName = $('Google Drive Trigger').item.json.name || 'unknown.pdf';
const fileId = $('Google Drive Trigger').item.json.id;
const triggeredAt = new Date().toISOString();

return {
  json: {
    fileName,
    fileId,
    triggeredAt,
    runId: `RUN-${Date.now()}`,
    status: 'STARTED',
    sourcePdfUrl: `https://drive.google.com/file/d/${fileId}/view`
  },
  binary: $input.item.binary
};

// Always re-attach binary from Download node so it's available for OCR later
const extractedText = $input.item.json.text || '';

if (extractedText.trim().length === 0) {
  return {
    json: {
      ...$input.item.json,
      ...$('Set Run Metadata').item.json,
      needsOCR: true,
      extractedText: ''
    },
    binary: $('Download PDF from Drive').item.binary
  };
}

return {
  json: {
    ...$input.item.json,
    ...$('Set Run Metadata').item.json,
    needsOCR: false,
    extractedText: extractedText
  },
  binary: $('Download PDF from Drive').item.binary
};

let rawContent = $input.item.json.message?.content
  || $input.item.json.choices?.[0]?.message?.content
  || $input.item.json[0]?.message?.content
  || '';

// Strip markdown fences if present
rawContent = rawContent.replace(/```json/gi, '').replace(/```/g, '').trim();

let parsedInvoice;
try {
  parsedInvoice = JSON.parse(rawContent);
} catch (e) {
  // Try to extract JSON object from the text
  const match = rawContent.match(/{[\s\S]*}/);
  if (match) {
    try {
      parsedInvoice = JSON.parse(match[0]);
    } catch (e2) {
      throw new Error('AI_PARSE_FAILED: ' + rawContent.substring(0, 300));
    }
  } else {
    throw new Error('AI_PARSE_FAILED: No JSON found in: ' + rawContent.substring(0, 300));
  }
}

// Carry forward all metadata from upstream
const meta = $('Check Extraction Quality').item.json;

return {
  json: {
    runId: meta.runId,
    fileName: meta.fileName,
    fileId: meta.fileId,
    triggeredAt: meta.triggeredAt,
    sourcePdfUrl: meta.sourcePdfUrl,
    extractionMethod: meta.extractionMethod || 'DIGITAL',
    invoice: parsedInvoice
  }
};

const inv = $input.item.json.invoice;
const errors = [];
const warnings = [];

// Check required fields
const requiredFields = [
  ['invoice_number', 'Invoice Number'],
  ['invoice_date', 'Invoice Date'],
  ['currency', 'Currency'],
  ['supplier.name', 'Supplier Name'],
  ['buyer.name', 'Buyer Name'],
  ['line_items', 'Line Items']
];

for (const [path, label] of requiredFields) {
  const parts = path.split('.');
  let val = inv;
  for (const p of parts) { val = val?.[p]; }
  if (val === null || val === undefined || val === '') {
    errors.push({ code: 'E001', field: path, message: `${label} is required but missing` });
  }
}

// Check line items have basics
if (Array.isArray(inv.line_items) && inv.line_items.length > 0) {
  inv.line_items.forEach((item, idx) => {
    const lineNum = item.line_number || (idx + 1);
    if (!item.description) errors.push({ code: 'E004', field: `line_items[${idx}].description`, message: `Line ${lineNum}: Description is required` });
    if (item.quantity === null || item.quantity === undefined) errors.push({ code: 'E005', field: `line_items[${idx}].quantity`, message: `Line ${lineNum}: Quantity is required` });
    if (item.unit_price === null || item.unit_price === undefined) errors.push({ code: 'E006', field: `line_items[${idx}].unit_price`, message: `Line ${lineNum}: Unit price is required` });
  });
} else if (!Array.isArray(inv.line_items) || inv.line_items.length === 0) {
  errors.push({ code: 'E009', field: 'line_items', message: 'Line items array is empty or missing' });
}

// Warnings only for totals (not errors - commercial invoices often have 0 VAT)
if ((inv.subtotal_excl_vat || 0) === 0 && (inv.total_incl_vat || 0) === 0) {
  warnings.push({ code: 'W005', field: 'totals', message: 'Both totals are 0 - may need manual check' });
}

const isValid = errors.length === 0;


return {
  json: {
    ...$input.item.json,
    validation: {
      isValid,
      errorCount: errors.length,
      warningCount: warnings.length,
      errors,
      warnings
    }
  }
};

// ============================================================
// OUTPUT EXACT ZB_1_Template.xlsx COLUMNS:
// A: Tariff Code
// B: Statistical Quantity
// C: Statistical UOM
// D: Declared Quantity
// E: Declared UOM
// F: Item Description 1
// G: Quantity Number
// H: Quantity Unit
// I: Country of Origin
// J: Dangerous Cargo
// K: Item Amount
// L: Ap Number
// ============================================================
const data = $input.item.json;
const inv = data.invoice;

const getTariffCode = (description) => {
  const desc = (description || '').toLowerCase();
  if (desc.includes('whisky') || desc.includes('whiskey') ||
      desc.includes('bourbon') || desc.includes('sherry') ||
      desc.includes('barrique') || desc.includes('kavalan') ||
      desc.includes('malt')) {
    return '2208.30.9000';
  }
  return '2208.90.9000';
};

const getBottlesPerCtn = (description) => {
  const desc = (description || '').toLowerCase();
  const match = desc.match(/x\s*(\d+)/);
  if (match) return parseInt(match[1], 10);
  if (desc.includes('1000ml')) return 6;
  if (desc.includes('360ml')) return 20;
  return 1;
};

const countryCode = inv.supplier?.country_code || '';

const zbRows = (inv.line_items || []).map((item) => {
  const statQty = item.quantity || 0;
  const bottlesPerCtn = getBottlesPerCtn(item.description);
  const declaredQty = statQty * bottlesPerCtn;
  const amount = item.line_total_excl_vat
    || (item.quantity && item.unit_price ? Math.round(item.quantity * item.unit_price * 100) / 100 : 0);

  return {
    json: {
      'Tariff Code':          getTariffCode(item.description),
      'Statistical Quantity': statQty,
      'Statistical UOM':      'CTN',
      'Declared Quantity':    declaredQty,
      'Declared UOM':         'BTL',
      'Item Description 1':   item.description || '',
      'Quantity Number':      statQty,
      'Quantity Unit':        'CTN',
      'Country of Origin':    countryCode,
      'Dangerous Cargo':      'N',
      'Item Amount':          amount,
      'Ap Number':            inv.invoice_number || ''
    }
  };
});

return zbRows;

