const data = $input.item.json;
const inv = data.invoice || {};
const validation = data.validation || {};

return {
  json: {
    runId: data.runId,
    fileName: data.fileName,
    fileId: data.fileId,
    sourcePdfUrl: data.sourcePdfUrl,
    invoiceNumber: inv.invoice_number || 'UNKNOWN',
    supplierName: inv.supplier?.name || 'UNKNOWN',
    extractionMethod: data.extractionMethod || 'UNKNOWN',
    triggeredAt: data.triggeredAt,
    failedAt: new Date().toISOString(),
    status: 'EXCEPTION',
    errorCount: validation.errorCount || 0,
    warningCount: validation.warningCount || 0,
    errors: validation.errors || [],
    warnings: validation.warnings || [],
    errorSummary: (validation.errors || []).map(e => `[${e.code}] ${e.field}: ${e.message}`).join(' | ')
  }
};

