// Extract OCR text from Mistral response
// and align it with the same structure as the digital path
const mistralResponse = $input.item.json;

// Mistral returns pages array with markdown per page
const extractedText = (mistralResponse.pages || [])
  .map(page => page.markdown || page.text || '')
  .join('\n\n')
  .trim();

if (!extractedText) {
  throw new Error('Mistral OCR returned empty text');
}

// Get metadata from Check Extraction Quality node
// Must match EXACTLY what Mark Digital Extraction outputs
const meta = $('Check Extraction Quality').item.json;

return {
  json: {
    runId: meta.runId,
    fileName: meta.fileName,
    fileId: meta.fileId,
    triggeredAt: meta.triggeredAt,
    sourcePdfUrl: meta.sourcePdfUrl,
    extractedText: extractedText,
    extractionMethod: 'MISTRAL_OCR',
    needsOCR: false
  }
};
